    # The strategy is to ensure that for every position (i, j),
    # we keep matrix_a[i][j] < matrix_b[i][j] and then check
    # if both matrices are strictly increasing.

    # Swap elements in-place if needed to maintain matrix_a[i][j] < matrix_b[i][j]
    for i in range(n):
        for j in range(m):
            if matrix_a[i][j] > matrix_b[i][j]:
                matrix_a[i][j], matrix_b[i][j] = matrix_b[i][j], matrix_a[i][j]

    # Check if both matrices are strictly increasing
    def is_matrix_increasing(mat):
        # Check rows
        for i in range(n):
            for j in range(m - 1):
                if mat[i][j] >= mat[i][j + 1]:
                    return False
        # Check columns
        for j in range(m):
            for i in range(n - 1):
                if mat[i][j] >= mat[i + 1][j]:
                    return False
        return True

    return is_matrix_increasing(matrix_a) and is_matrix_increasing(matrix_b)

